import{_ as c,C as l,o as h,c as i,ak as o,E as a,j as e,a as r}from"./chunks/framework.DxrHb2fb.js";const q=JSON.parse('{"title":"ColorSwatch 颜色色块","description":"","frontmatter":{},"headers":[],"relativePath":"components/color-swatch.md","filePath":"components/color-swatch.md","lastUpdated":1790043131000}'),s={name:"components/color-swatch.md"};function n(b,t,u,p,m,x){const d=l("XhDemo");return h(),i("div",null,[t[0]||(t[0]=o('<h1 id="colorswatch-颜色色块" tabindex="-1">ColorSwatch 颜色色块 <a class="header-anchor" href="#colorswatch-颜色色块" aria-label="Permalink to &quot;ColorSwatch 颜色色块&quot;">​</a></h1><p>把一个颜色绘制为一小块用于展示：主题色一览、图例中的一格、当前选中的颜色。它只负责表达“这是什么颜色”，不接受点击、不修改值；需要挑选颜色时使用<a href="./color-picker">颜色选择器</a>。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/color-swatch" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/color-swatch.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/color-swatch" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/color-swatch" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/color-swatch.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>把颜色串绘制为一小块：颜色旁边写出串本身，可见也可读</p>',5)),a(d,{src:"color-swatch/01-basic"}),t[1]||(t[1]=o('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;color-swatch&quot;</code>：<strong><code>root</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="尺寸" tabindex="-1">尺寸 <a class="header-anchor" href="#尺寸" aria-label="Permalink to &quot;尺寸&quot;">​</a></h3><p>sm / md / lg 三档改变边长与棋盘格粒度，圆角恒为内嵌档</p>',6)),a(d,{src:"color-swatch/02-sizes"}),t[2]||(t[2]=e("h3",{id:"透明度",tabindex:"-1"},[r("透明度 "),e("a",{class:"header-anchor",href:"#透明度","aria-label":'Permalink to "透明度"'},"​")],-1)),t[3]||(t[3]=e("p",null,"半透明颜色铺在棋盘格上，可以看出这是带透明度的颜色；三种写法解析为同一个颜色",-1)),a(d,{src:"color-swatch/03-alpha"}),t[4]||(t[4]=e("h3",{id:"图例与无效值",tabindex:"-1"},[r("图例与无效值 "),e("a",{class:"header-anchor",href:"#图例与无效值","aria-label":'Permalink to "图例与无效值"'},"​")],-1)),t[5]||(t[5]=e("p",null,"label 为读屏提供有含义的名字；无法解析的串只剩棋盘格并标为无效",-1)),a(d,{src:"color-swatch/04-legend"}),t[6]||(t[6]=o('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>在文字旁直观标出一个颜色：图例、标签、主题预览。</li><li>与颜色串并排展示，让用户既能看到也能读出。</li><li>作为其他控件中表示当前颜色的小块（颜色选择器的触发按钮使用的就是这一族）。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>用户需要在若干固定颜色中选一个时，使用<a href="./color-swatch-picker">颜色色块选择器</a>，它每格的色块面使用的就是这一族。</li><li>用户需要自由调色时，使用<a href="./color-picker">颜色选择器</a>。</li><li>只是给一段文字加底色或强调时，属于排版范畴，不使用颜色色块。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>支持 <code>#rgb</code> / <code>#rrggbb(aa)</code>、<code>rgb()</code> / <code>rgba()</code>、<code>hsl()</code> / <code>hsla()</code>；无法解析时只绘制棋盘格底并带 <code>data-invalid</code>，不静默绘制为黑色。</li><li>半透明颜色铺在棋盘格上，能看出这是带透明度的颜色，而不是与页面底色混合成另一种颜色。</li><li>尺寸 sm / md / lg 三档改变边长与棋盘格粒度，圆角固定为内嵌档。</li><li>读屏按 <code>label</code> 读出，其次读颜色串；两者都没有时整块视为装饰。</li><li>高对比模式下退出强制着色以保留原色，描边换成系统前景色勾出轮廓；打印时保留底色。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>与<a href="./tag">标签</a>、<a href="./list">列表</a>条目并排作为图例；与<a href="./color-picker">颜色选择器</a>搭配时，选择器的触发按钮自带同族色块，不需要再放一个。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>颜色有含义时提供 <code>label</code>（“品牌红”“已完成”），只读出 <code>#e11d48</code> 无法表达含义。</li><li>色块旁写出颜色串或名称，颜色不能是唯一的信息通道。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>将它当作按钮：色块不接受交互。</li><li>传颜色关键字（<code>red</code>、<code>transparent</code>）：不在支持的写法内，会被判定为无效。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-color-swatch&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhColorSwatch</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/color-swatch.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>读屏朗读该颜色的方式，例如「品牌红」。 未提供时朗读颜色串本身；串也没有时整块视为装饰，不进入可访问树。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，影响色块的边长与棋盘格粒度。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>要展示的颜色串。识别 <code>#rgb</code> / <code>#rrggbb(aa)</code>、<code>rgb()</code> / <code>rgba()</code>、<code>hsl()</code> / <code>hsla()</code>， 不识别颜色关键字。无法解析时色块只保留棋盘格底，并带 <code>data-invalid</code>。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td>原样透出的颜色串（未解析时也是它，使 data-value 与作者书写的一致）。</td></tr><tr><td><code>valid</code></td><td><code>boolean</code></td><td>颜色串解析成功。失败时 rgba 为兜底黑、色块只绘制棋盘格。</td></tr><tr><td><code>rgba</code></td><td><code>ColorRgba</code></td><td></td></tr><tr><td><code>css</code></td><td><code>string</code></td><td>绘制进色块的 CSS 颜色（rgba() 写法，带透明度）；解析失败时为空串。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>色块本体：role=img，名字取 label，其次取颜色串。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-hidden</code></td><td>undefined | &#39;true&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.label</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;img&#39; | undefined</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/color-swatch.css</code> 使用 <code>[data-scope=&quot;color-swatch&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-value</code></td><td>value || undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-swatch</code></td><td>&#39;&#39;</td></tr><tr><td><code>root</code></td><td><code>data-xh-swatch-size</code></td><td>props.size</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-color-swatch-border</code></td><td><code>root</code></td><td><code>--xh-swatch-border</code></td><td><code>default</code></td><td><code>--xh-border-default</code></td><td>color-swatch 的 root 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-border-invalid</code></td><td><code>root</code></td><td><code>--xh-swatch-border</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>color-swatch 的 root 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-radius</code></td><td><code>root</code></td><td><code>--xh-swatch-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>color-swatch 的 root 部件 --xh-swatch-radius 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-size</code></td><td><code>root</code></td><td><code>--xh-swatch-size</code></td><td><code>default</code></td><td><code>--xh-_swatch-size</code></td><td>color-swatch 的 root 部件 --xh-swatch-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p>',39))])}const g=c(s,[["render",n]]);export{q as __pageData,g as default};
